        scope["_parent"]["attachMovie"]("MiniMiniMeteor", "MiniMiniMeteor" + scope["_parent"]["getNextHighestDepth"](), scope["_parent"]["getNextHighestDepth"](), obj({{"_x", scope["_x"]}, {"_y", scope["_y"]}, {"count", 300}}));
