//   Course Clips/8-Randomized Metoer / layer 'Layer 2' / frame 3
void frame_5693_1(Activation& scope) {
    stop();
    //Re = function () {
    scope["_rotation"] = random(360);
    scope["rotspeed"] = (random(10) - 5) / 2;
    scope["speed"] = 3 + Math["random"]() * 2;
    //dir = 7;
    scope["_y"] = -_root["Course"]["BackGFX"]["_y"] - 500 - random(500);
    scope["_x"] = -_root["Course"]["BackGFX"]["_x"] + Math["random"]() * 1000 - 500;
    scope["mariox"] = _root["Course"]["Char"]["_x"] - _root["Course"]["BackGFX"]["_x"];
    scope["marioy"] = _root["Course"]["Char"]["_y"] - _root["Course"]["BackGFX"]["_y"];
    //
    scope["dy"] = scope["_y"] - scope["marioy"];
    scope["dx"] = scope["_x"] - scope["mariox"];
    scope["rot"] = Math["atan2"](scope["dy"], scope["dx"] + Math["random"]() * 1000 - 500);
    scope["yspeed"] = -Math["sin"](scope["rot"]) * scope["speed"];
    scope["xspeed"] = -Math["cos"](scope["rot"]) * scope["speed"];
    scope["_alpha"] = 100;
    scope["bcount"] = 100 + random(1000);
    scope["count"] = 0;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (_root["PauseGame"] == false) {
            scope["_rotation"] += scope["rotspeed"];
            scope["_x"] += scope["xspeed"];
            scope["_y"] += scope["yspeed"];
            //
            if (scope.self["body"]["hitTest"](_root["Course"]["Char"]["charClip"]["body"])) {
                if ((strictNotEquals(_root["Course"]["Char"]["attackFrame"], "SlingStar") && strictNotEquals(_root["Course"]["Char"]["attackFrame"], "JumpSpin")) || _root["Course"]["Char"]["attack"] == false) {
                    if (_root["Course"]["Char"]["_x"] > scope["_x"] + scope["_parent"]["_x"]) {
                        _root["MarioHit"](1, 90, -5, 7, 7, "");
                    } else {
                        _root["MarioHit"](1, 90, -5, -7, 7, "");
                    }
                }
                scope["Explode"]();
            }
            if (scope["count"]++ > scope["bcount"]) {
                scope["Explode"]();
            }
            //
        }
        return undefined;
    });
    //};
}

