//   Course Clips/9-03SwitchGround / layer 'Layer 2' / frame 1
void frame_6514_0(Activation& scope) {
    scope["Y"] = 0;
    scope["count"] = 0;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (_root["Course"]["BackGFX"]["Switched"] == "gone") {
            scope["_y"] += 160;
            scope["onEnterFrame"] = Value::null();
        }
        if (_root["Course"]["BackGFX"]["Switched"] == true) {
            scope["count"]++;
            _root["playpause"] = true;
            if (scope["Y"] < 120) {
                _root["Camcenter"] = scope.self;
            }
            if (scope["count"] > 32) {
                if (strictNotEquals(scope["sounded"], true)) {
                    scope["sounded"] = true;
                    _root["Mariosound"] = new_(Sound, scope.self);
                    _root["Mariosound"]["attachSound"]("WaterGurgle");
                    _root["Mariosound"]["start"](0, 1);
                    _root["Mariosound"]["setVolume"](_root["MarioVolume"]);
                }
                if (scope["count"] % 2 == 0) {
                    scope["_x"] += 2;
                } else {
                    scope["_x"] -= 2;
                }
                scope["_y"] += 3;
                scope["Y"] += 3;
                //Include Cam Center on this... Robert!!
                if (scope["Y"] > 160) {
                    _root["playpause"] = false;
                    scope["onEnterFrame"] = Value::null();
                    //Cam Center Stuff
                }
            }
        }
        return undefined;
    });
    //
}

